import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { isBuildActive } from "@/lib/claude-console-core";

/**
 * Live Matrix status for the sidebar tag.
 *
 *   GET /api/claude/console-status
 *     -> { running: number, needsAttention: number, lastEventAt: string | null }
 *
 * Session-gated (a caller only ever sees their OWN builds). Polled by the portal
 * Shell to drive the "running" / "update ready" tag next to the Matrix nav item.
 * Fails soft: any error returns a zeroed payload so the tag simply stays dark.
 *
 *   - running        = builds still in flight (planning / queued / running)
 *   - needsAttention = plans waiting for the owner to approve
 *   - lastEventAt    = most recent time a build reached a state worth surfacing
 *                      (finished DONE/FAILED, or a plan became AWAITING_APPROVAL);
 *                      the client compares it against a locally-stored "last seen"
 *                      to decide whether to show the "update ready" tag.
 */
export const dynamic = "force-dynamic";

const ATTENTION_STATUSES = new Set(["AWAITING_APPROVAL", "DONE", "FAILED"]);

export async function GET() {
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  try {
    const rows = await db.claudeBuild.findMany({
      where: { userId: user.id },
      orderBy: { updatedAt: "desc" },
      take: 50,
      select: { status: true, updatedAt: true },
    });

    let running = 0;
    let needsAttention = 0;
    let lastEventAt: Date | null = null;
    for (const r of rows) {
      if (r.status === "AWAITING_APPROVAL") needsAttention++;
      // "running" excludes AWAITING_APPROVAL — that's waiting on the user, not work in flight.
      else if (isBuildActive(r.status)) running++;
      if (ATTENTION_STATUSES.has(r.status) && (!lastEventAt || r.updatedAt > lastEventAt)) {
        lastEventAt = r.updatedAt;
      }
    }

    return NextResponse.json({
      running,
      needsAttention,
      lastEventAt: lastEventAt ? lastEventAt.toISOString() : null,
    });
  } catch {
    // Fail soft — a status tag must never break the portal.
    return NextResponse.json({ running: 0, needsAttention: 0, lastEventAt: null });
  }
}
import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";

export const dynamic = "force-dynamic";

/**
 * GET /api/claude/[id]
 * Ownership-checked live status for a ClaudeBuild — polled by the client viewer.
 * Returns { status, steps, log, plan }. `plan` is the JSON string of proposed
 * commands (present once the build reaches AWAITING_APPROVAL), or null.
 */
export async function GET(
  _req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;

  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const build = await db.claudeBuild.findUnique({
    where: { id },
    select: { userId: true, status: true, steps: true, log: true, plan: true },
  });
  if (!build || (build.userId !== user.id && user.role !== "ADMIN")) {
    return NextResponse.json({ error: "not found" }, { status: 404 });
  }

  return NextResponse.json(
    { status: build.status, steps: build.steps, log: build.log, plan: build.plan },
    { headers: { "cache-control": "no-store" } }
  );
}

